using Cogpunk.Core.Templates;
using Microsoft.Xna.Framework;
using Terraria;
using Terraria.ID;
using Terraria.ModLoader;

namespace Cogpunk.Content.Coghaven.Tiles
{
	/// <summary>
	/// Jade Roof Tiles (2026-11-06): green glazed roof tiles, tubes and channels with a gold-glazed tube now and then: the curved roofs of Coghaven's palace. Generated by <see cref="Generation.CoghavenPass"/>; seamless clump art from art/coghaven/make_coghaven_art.py.
	/// </summary>
	public class JadeRoofTile : CogpunkTile
	{
		public override void SetStaticDefaults() {
			TileID.Sets.GeneralPlacementTiles[Type] = false;   // later world-gen features (other mods) keep off the palace
			Main.tileSolid[Type] = true;
			Main.tileBlockLight[Type] = true;
			DustType = DustID.GemEmerald;
			HitSound = SoundID.Tink;
			AddMapEntry(new Color(30, 114, 88), CreateMapEntryName());
			RegisterItemDrop(ModContent.ItemType<Items.JadeRoof>());
		}
	}
}
